{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Histologically confirmed diagnosis of invasive BCC, with acceptable histologic subtypes including nodular, morpheaform, metatypical, superficial, micronodular, infiltrative, mixed, basosquamous, keratotic, desmoplastic.",
      "quote": "Histologically confirmed diagnosis of invasive BCC",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Patients must be deemed unlikely to benefit from further therapy with an HHI due to prior progression on HHI therapy, intolerance (Grade 3/4 AE or specific Grade 2 events with ≥3 months exposure), or no better than stable disease after 9 months on HHI therapy.",
      "quote": "Patients must be deemed unlikely to benefit from further therapy with an HHI",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "At least 1 lesion measurable by study criteria. For Group 1: ≥10 mm in maximal diameter (1.5 cm short axis for lymph nodes) per RECIST 1.1. For Group 2: both perpendicular diameters ≥10 mm by digital photography, or if measured by MRI/CT, ≥10 mm in longest dimension.",
      "quote": "At least 1 lesion that is measurable by study criteria",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "ECOG performance status ≤1.",
      "quote": "Eastern Cooperative Oncology Group (ECOG) performance status ≤1",
      "thresholds": [
        {"test": "ECOG performance status", "op": "<=", "value": 1, "unit": null}
      ]
    },
    {
      "kind": "inclusion",
      "text": "At least 18 years old.",
      "quote": "At least 18 years old",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Hepatic function: Total bilirubin ≤3.0x ULN (or ≤3x ULN if liver metastases), transaminases ≤3x ULN (or ≤5x ULN if liver metastases), ALP ≤2.5x ULN (or ≤5x ULN if liver or bone metastases). Additional criteria for Group 1 with hepatic metastases.",
      "quote": "Total bilirubin ≤3.0x upper limit of normal (ULN) (or ≤3x ULN, if liver metastases)",
      "thresholds": [
        {"test": "Total bilirubin", "op": "<=", "value": 3.0, "unit": "x ULN"},
        {"test": "Transaminases", "op": "<=", "value": 3, "unit": "x ULN"},
        {"test": "ALP", "op": "<=", "value": 2.5, "unit": "x ULN"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Renal function: Serum creatinine ≤2x ULN or estimated creatinine clearance >35 mL/min (Cockcroft-Gault).",
      "quote": "Serum creatinine ≤2x ULN or estimated creatinine clearance >35 mL/min",
      "thresholds": [
        {"test": "Serum creatinine", "op": "<=", "value": 2, "unit": "x ULN"},
        {"test": "Creatinine clearance", "op": ">", "value": 35, "unit": "mL/min"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Creatine phosphokinase (CPK) elevation ≤ grade 2.",
      "quote": "Creatine phosphokinase (CPK) (also known as CK [creatine kinase]) elevation ≤ grade 2",
      "thresholds": [
        {"test": "CPK elevation", "op": "<=", "value": 2, "unit": "grade"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Bone marrow function: Hemoglobin ≥9.0 g/dL, ANC ≥1.5 x 10^9/L, platelet count ≥75 x 10^9/L.",
      "quote": "Hemoglobin ≥9.0 g/dL",
      "thresholds": [
        {"test": "Hemoglobin", "op": ">=", "value": 9.0, "unit": "g/dL"},
        {"test": "ANC", "op": ">=", "value": 1.5, "unit": "10^9/L"},
        {"test": "Platelet count", "op": ">=", "value": 75, "unit": "10^9/L"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Anticipated life expectancy >12 weeks.",
      "quote": "Anticipated life expectancy >12 weeks",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "All patients must consent to provide archived or newly obtained tumor material (FFPE block or 10 unstained/stained slides) for central pathology review, confirmed received prior to enrollment.",
      "quote": "All patients in either group must consent to provide archived or newly obtained tumor material",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Group 2 only: Patients must consent to undergo biopsies of externally visible BCC lesions at baseline, cycle 1 day 22, at progression, and other clinically indicated times.",
      "quote": "Group 2 only (unresectable locally advanced BCC): Patients must consent to undergo biopsies of externally visible BCC lesions",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Willing and able to comply with clinic visits and study-related procedures.",
      "quote": "Willing and able to comply with clinic visits and study-related procedures",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Provide signed informed consent prior to any screening procedures (except brain MRI allowed within 60 days of enrollment).",
      "quote": "Provide signed informed consent prior to any screening procedures",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Group 2 only: Patients must be deemed to have unresectable disease, with surgery contraindicated per Mohs surgeon, head/neck surgeon, or plastic surgeon, and consultation note submitted.",
      "quote": "Group 2 only: Patients in Group 2 must be deemed to have unresectable disease.",
      "thresholds": []
    },
    {
      "kind": "inclusion",
      "text": "Group 2 only: Patients must be deemed not appropriate for radiation therapy, meeting at least one criterion: prior radiation exceeding acceptable cumulative dose, unlikely to respond per radiation oncologist, or multidisciplinary team assessment indicating contraindication.",
      "quote": "Group 2 Only: Patients in Group 2 must be deemed as not appropriate for radiation therapy.",
      "thresholds": []
    }
  ]
}
